import{_ as i,o as a,c as n,ai as l}from"./chunks/framework.Ai2o9gNv.js";const c=JSON.parse('{"title":"45-泛型-接口-类-结构体","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/45-泛型-接口-类-结构体/45-泛型-接口-类-结构体.md","filePath":"仓颉入门到实战/45-泛型-接口-类-结构体/45-泛型-接口-类-结构体.md","lastUpdated":1736994114000,"__rawMarkdown":"# 45-泛型-接口-类-结构体\\n\\n## 泛型接口\\n\\n泛型可以用来定义泛型接口，以标准库中定义的 `Iterable` 为例，它需要返回一个 `Iterator` 类型，这一类型是一个容器的遍历器。 `Iterator` 是一个泛型接口，`Iterator` 内部有一个从容器类型中返回下一个元素的 `next` 成员函数，`next` 成员函数返回的类型是一个需要在使用时指定的类型，所以 `Iterator` 需要声明泛型参数。\\n\\n```javascript\\npublic interface Iterable<E> {\\n    func iterator(): Iterator<E>\\n}\\n\\npublic interface Iterator<E> <: Iterable<E> {\\n    func next(): Option<E>\\n}\\n\\npublic interface Collection<T> <: Iterable<T> {\\n     prop size: Int64\\n     func isEmpty(): Bool\\n}\\n```\\n\\n## 泛型类\\n\\n[泛型接口](https://docs.cangjie-lang.cn/docs/0.53.13/user_manual/source_zh_cn/generic/generic_interface.html)中介绍了泛型接口的定义和使用，本节我们介绍泛型类的定义和使用。如 `Map` 的键值对就是使用泛型类来定义的。\\n\\n可以看一下 `Map` 类型中的键值对 `Node` 类型就可以使用泛型类来定义：\\n\\n```javascript\\npublic open class Node<K, V> where K <: Hashable & Equatable<K> {\\n    public var key: Option<K> = Option<K>.None\\n    public var value: Option<V> = Option<V>.None\\n\\n    public init() {}\\n\\n    public init(key: K, value: V) {\\n        this.key = Option<K>.Some(key)\\n        this.value = Option<V>.Some(value)\\n    }\\n}\\n```\\n\\n由于键与值的类型有可能不相同，且可以为任意满足条件的类型，所以 `Node` 需要两个类型形参 `K` 与 `V` ，`K <: Hashable, K <: Equatable<K>` 是对于键类型的约束，意为 `K` 要实现 `Hashable` 与 `Equatable<K>` 接口，也就是 `K` 需要满足的条件。对于泛型约束，详见[泛型约束](https://docs.cangjie-lang.cn/docs/0.53.13/user_manual/source_zh_cn/generic/generic_constraint.html)章节。\\n\\n## 泛型结构体\\n\\nstruct 类型的泛型与 class 是类似的，下面我们可以使用 struct 定义一个类似于二元元组的类型：\\n\\n```javascript\\nstruct Pair<T, U> {\\n    let x: T\\n    let y: U\\n    public init(a: T, b: U) {\\n        x = a\\n        y = b\\n    }\\n    public func first(): T {\\n        return x\\n    }\\n    public func second(): U {\\n        return y\\n    }\\n}\\n\\nmain() {\\n    var a: Pair<String, Int64> = Pair<String, Int64>(\\"hello\\", 0)\\n    println(a.first())\\n    println(a.second())\\n}\\n```\\n\\n程序输出的结果为：\\n\\n```text\\nhello\\n0\\n```\\n\\n在 `Pair` 中我们提供了 `first` 与 `second` 两个函数来取得元组的第一个与第二个元素。"}'),p={name:"仓颉入门到实战/45-泛型-接口-类-结构体/45-泛型-接口-类-结构体.md"};function t(h,s,e,k,r,E){return a(),n("div",null,[...s[0]||(s[0]=[l("",15)])])}const g=i(p,[["render",t]]);export{c as __pageData,g as default};
